          if (line.startsWith('rename to ') || line.startsWith('copy to ')) {
            currentFile.name = detachString(
              decodeDiffFileName(
                line.slice(
                  line.startsWith('rename')
                    ? 'rename to '.length
                    : 'copy to '.length
                )
              )
            );
          }
