    String.raw`"\400"`,
    String.raw`"\777"`,
    String.raw`"\800"`,
    String.raw`"prefix\303\274\12"`,
    String.raw`"prefix\303\274\q"`,
  ])('returns no result for %j', (input) => {
    expect(parseQuotedDiffFileName(input)).toBeUndefined();
  });
});

