/**
 * A toggle pill built as one native control: a `<label>` wrapping a
 * visually-hidden checkbox styled to look like a switch.
 */
export function ToggleSwitch({
  label,
  icon,
  checked,
  onCheckedChange,
  disabled = false,
  title,
