      newText: 'F',
    },
  ])!;
  tokenizeLineCount = 0;
  tokenizer.tokenize(change, {
    startingLine: 0,
    totalLines: 1,
    bufferBefore: 0,
    bufferAfter: 0,
  });

  expect(tokenizeLineCount).toBe(1);
