    const { cleanup, content, editor, file, window } =
      await createEditorFixture('alpha\nbravo\ncharlie');

    try {
      // A plain File can provide a viewport for focus and scrolling without
      // taking ownership of realigning its rendered rows after document edits.
      const viewport = document.createElement('div');
      const editableFile: DiffsEditableComponent<undefined> = file;
      editableFile.getEditorViewport = () => viewport;
      // Seed cached grammar states so Enter can stop once syntax state settles.
      editor.applyEdits([
        {
          range: {
            start: { line: 0, character: 0 },
            end: { line: 0, character: 5 },
          },
          newText: 'ALPHA',
        },
      ]);
      editor.setState({ selections: [caret(1, 3)] });

      content.dispatchEvent(
        new window.InputEvent('beforeinput', {
          bubbles: true,
          cancelable: true,
          composed: true,
          inputType: 'insertParagraph',
        })
      );

      expect(editor.getText()).toBe('ALPHA\nbra\nvo\ncharlie');
      expect(
        Array.from(
          content.querySelectorAll<HTMLElement>('[data-line]'),
          (row) => row.textContent
        )
      ).toEqual(['ALPHA', 'bra', 'vo', 'charlie']);
      expect(editor.getState().selections).toEqual([caret(2, 0)]);
    } finally {
      cleanup();
    }
  });

  test('deletes to the end of the line with macOS control+k', async () => {
    const { cleanup, content, editor, window } =
      await createEditorFixture('hello world\nnext');

